use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut iter = input.split_whitespace();

    let n: usize = iter.next().unwrap().parse().unwrap();
    let mut count = vec![0_i64; n + 1];
    let mut position_sum = vec![0_i64; n + 1];
    let mut answer = 0_i64;

    for position in 1..=n {
        let value: usize = iter.next().unwrap().parse().unwrap();
        let pos = position as i64;
        let previous_count = count[value];

        answer += previous_count * (pos - 1)
            - position_sum[value]
            - previous_count * (previous_count - 1) / 2;

        count[value] += 1;
        position_sum[value] += pos;
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    writeln!(out, "{answer}").unwrap();
}
```

